go.signature:
package benchmark

type OrderState uint8
const (
    Draft OrderState = iota
    Submitted
    Paid
    Shipped
    Cancelled
)

type OrderEvent uint8
const (
    Submit OrderEvent = iota
    Pay
    Ship
    Cancel
)

type TransitionError uint8
const (
    EventNotAllowed TransitionError = iota
    TerminalState
)

type TransitionResult interface{ isTransitionResult() }
type Accepted struct{ State OrderState }
func (Accepted) isTransitionResult() {}
type Rejected struct{ Error TransitionError }
func (Rejected) isTransitionResult() {}

func Transition(state OrderState, event OrderEvent) TransitionResult

rust.signature:
#[derive(Debug, PartialEq, Eq)]
pub enum OrderState { Draft, Submitted, Paid, Shipped, Cancelled }
pub enum OrderEvent { Submit, Pay, Ship, Cancel }
#[derive(Debug, PartialEq, Eq)]
pub enum TransitionError { EventNotAllowed, TerminalState }
#[derive(Debug, PartialEq, Eq)]
pub enum TransitionResult { Accepted(OrderState), Rejected(TransitionError) }
pub fn transition(state: OrderState, event: OrderEvent) -> TransitionResult
